def get_total_x(a: list[int], b: list[int]) -> int:
    import math
    def lcm(x, y):
        return (x * y) // math.gcd(x, y)
    l = a[0]
    for num in a[1:]:
        l = lcm(l, num)
    g = b[0]
    for num in b[1:]:
        g = math.gcd(g, num)
    count = 0
    mult = l
    while mult <= g:
        if g % mult == 0:
            count += 1
        mult += l
    return count
